        void BuildCollection(){var page=Page(collectionScroll);var toolbar=new Panel{Dock=DockStyle.Top,Height=88};collectionScroll.BringToFront();page.Controls.Add(toolbar);collectionScroll.BringToFront();var searchLabel=Label("SEARCH",new Rectangle(0,3,300,18),8,true,Palette.Muted);toolbar.Controls.Add(searchLabel);search.Bounds=new Rectangle(2,27,300,26);search.BackColor=Palette.Raised;search.ForeColor=Palette.Text;search.BorderStyle=BorderStyle.FixedSingle;search.Font=Palette.Font(11);search.AccessibleName="Search characters";search.TextChanged+=(s,e)=>ApplyFilter();var searchField=new StudioInput(search){Bounds=new Rectangle(0,25,300,36)};toolbar.Controls.Add(searchField);filter.Bounds=new Rectangle(316,27,200,28);filter.DropDownStyle=ComboBoxStyle.DropDownList;filter.FlatStyle=FlatStyle.Flat;filter.BackColor=Palette.Raised;filter.ForeColor=Palette.Text;filter.Items.AddRange(new object[]{"Featured collection","All characters","Unlocked","Customizable","Signatures"});filter.DrawMode=DrawMode.OwnerDrawFixed;filter.ItemHeight=23;filter.DrawItem+=(s,e)=>{using(var b=new SolidBrush(Palette.Raised))e.Graphics.FillRectangle(b,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,Convert.ToString(filter.Items[e.Index]),filter.Font,e.Bounds,Palette.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.NoPrefix);};filter.SelectedIndex=0;filter.SelectedIndexChanged+=(s,e)=>ApplyFilter();filter.AccessibleName="Filter characters";toolbar.Controls.Add(filter);countLabel.Bounds=new Rectangle(0,60,600,22);countLabel.ForeColor=Palette.Muted;countLabel.Font=Palette.Font(8);toolbar.Controls.Add(countLabel);toolbar.Resize+=(s,e)=>{int w=toolbar.ClientSize.Width;filter.Width=Math.Min(200,w/2);filter.Left=w-filter.Width;searchField.Width=Math.Max(100,filter.Left-14);countLabel.Width=w;};collectionScroll.Content.FlowDirection=FlowDirection.LeftToRight;collectionScroll.Content.WrapContents=true;foreach(int role in Enumerable.Range(0,Adventure.Roles.Length).OrderB