        void ApplyFilter(){if(tiles.Count==0)return;var term=search.Text.Trim();int shown=0;foreach(var tile in tiles){int role=tile.RoleIndex;bool include=filter.SelectedIndex==1||filter.SelectedIndex==0&&(role==0||role==draft.Role||Adventure.IsFixedDesign(role))||filter.SelectedIndex==2&&Adventure.CanEquip(role,journey.Level)||filter.SelectedIndex==3&&!Adventure.IsFixedDesign(role)||filter.SelectedIndex==4&&Adventure.IsFixedDesign(role);bool show=include&&(term.Length==0||Adventure.Roles[role].IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0);tile.Visible=show;if(show)shown++;}countLabel.Text=shown+" characters · Select a card to preview";collectionScroll.ScrollTo(0);LayoutTiles();}
