        void AddOptions(string key,string[] values,Color[] colors,bool hair){var group=Group(key,hair?108:74,"personal-only");var row=new FlowLayoutPanel{Bounds=new Rectangle(0,26,620,hair?80:44),WrapContents=true,Margin=Padding.Empty,Tag="options"};var items=new List<StyleOption>();for(int i=0;i<values.Length;i++){int index=i;var option=new StyleOption{Text=values[i],AccessibleName=key+": "+values[i]};if(colors!=null){option.Swatch=colors[i];option.Size=new Size(36,36);hints.SetToolTip(option,values[i]);}else if(hair){option.Size=new Size(82,74);}else option.Width=key=="Look"?105:95;option.Click+=(s,e)=>{SetValue(key,index);Save(true);};items.Add(option);row.Controls.Add(option);}options.Add(key,items);group.Controls.Add(row);styleScroll.Content.Controls.Add(group);}
        int Value(string key){switch(key){case "Look":return draft.Look;case "Hair":return draft.Hair;case "Hair colour":return draft.HairColour;case "Skin tone":return draft.Skin;case "Outfit colour":return draft.Shirt;case "Expression":return draft.Eyes;default:return draft.Element;}}
        void SetValue(string key,int value){switch(key){case "Look":draft.Look=value;break;case "Hair":draft.Hair=value;break;case "Hair colour":draft.HairColour=value;break;case "Skin tone":draft.Skin=value;break;case "Outfit colour":draft.Shirt=value;break;case "Expression":draft.Eyes=value;break;default:draft.Element=value;break;}}
        void UpdateStyle(){bool fixedDesign=Adventure.IsFixedDesign(draft.Role);foreach(Control group in styleScroll.Content.Controls){if(Convert.ToString(group.Tag)=="personal-only"){group.Visible=!fixedDesign;group.Enabled=!fixedDesign;}if(Convert.ToString(group.Tag)=="fixed-only")group.Visible=fixedDesign;}foreach(var item in options){for(int i=0;i<item.Value.Count;i++){var option=item.Value[i];option.Selected=Value(item.Key)==i;if(item.Key=="Hair"){var p=draft.Copy();p.Role=0;p.Hair=i;option.HairPreview=p;}option.Invalidate();}}LayoutStyle();}
        void LayoutStyle(){int width=Math.Max(150,styleScroll.Content.ClientSize.Width-8);foreach(Control group in styleScroll.Content.Controls){if(group is SoftButton)continue;group.Width=width;foreach(Control child in group.Controls){var row=child as FlowLayoutPanel;if(row!=null)row.Width=width;else if(child is TextBox||Convert.ToString(child.Tag)=="input")child.Width=width-4;else if(child is Label)child.Width=width;}}styleScroll.RefreshContent();}
