        HeroProfile Profile(int role){var p=draft.Copy();p.Role=role;return p;}int SelectedRole{get{return previewRole<0?draft.Role:previewRole;}}int SelectedOutfitLevel{get{return previewRole<0?journey.Level:previewLevel;}}bool SelectedHasSkill{get{return CharacterSkills.HasForOutfit(SelectedRole,SelectedOutfitLevel);}}
        void Preview(int role,int level){skill.Stop();previewRole=role;previewLevel=level;UpdateHero();TryAutoSkill();}
        void Equip(int role){if(!Adventure.CanEquip(role,journey.Level))return;skill.Stop();draft.Role=role;previewRole=-1;previewLevel=0;Save(true);UpdateStyle();ApplyFilter();TryAutoSkill();}
        void Save(bool appearance){if(journey.SaveProfile(draft)){draft.Name=journey.Profile.Name;draft.KeepAppearance(journey.Profile);saveStatus.Text="Saved automatically";saveStatus.ForeColor=Palette.Muted;if(appearance){foreach(var tile in tiles)tile.UpdateProfile(draft);UpdateStyle();}UpdateHero();changed();}else{saveStatus.Text="Could not save changes";saveStatus.ForeColor=Color.Salmon;}}
        void TryAutoSkill(){if(CharacterSkills.CanAutoUse(draft,SelectedRole,journey.Level))StartSkill();}
        void ToggleSkill(){if(skill.Running)skill.Stop();else StartSkill();}
        void StartSkill(){if(!SelectedHasSkill||!skill.Start(Profile(SelectedRole)))return;hero.Visible=false;skill.Visible=true;skill.BringToFront();signature.Text="Stop";signature.Selected=true;signature.Invalidate();gearName.Text=skill.Caption;}
        public void RefreshProgress(){int selected=SelectedRole;bool unlockedBefore=knownLevel>=CharacterSkills.UnlockLevel(selected);bool levelChanged=knownLevel!=journey.Level;if(levelChanged){knownLevel=journey.Level;foreach(var tile in tiles)tile.UpdateLevel(knownLevel);}levelLabel.Text="LEVEL "+journey.Level;xpLabel.Text=journey.Level==100?"Maximum level · "+journey.Xp.ToString("N0")+" XP":(journey.Xp-Adventure.Threshold(journey.Level))+" / "+(Adventure.Threshold(journey.Level+1)-Adventure.Threshold(journey.Level))+" XP to Level "+(journey.Level+1);xpBar.Xp=journey.Xp;xpBar.Invalidate();UpdateHero();if(levelChanged)ApplyFilter();if(!unlockedBefore&&journey.Level>=CharacterSkills.UnlockLevel(selected))TryAutoSkill();}
        void UpdateHero(){if(heroName.IsDisposed)return;int role=SelectedRole,at=previewRole<0?journey.Level:previewLevel;bool skillHere=CharacterSkills.HasForOutfit(role,at);if(!skillHere)skill.Stop();skill.Configure(Profile(role));hero.Visible=!skill.Running;skill.Visible=skill.Running;hero.Profile=Profile(role);hero.Level=journey.Level;hd.Selected=!draft.PixelPreview;pixel.Selected=draft.PixelPreview;hd.Invalidate();pixel.Invalidate();hero.GearLevel=at;heroName.Text=role==0?HeroProfile.CleanName(draft.Name):Adventure.Roles[role];gearName.Text=skill.Running?skill.Caption:role==0?"Customizable · your personal look":Adventure.Gear(role,at).Title;starter.Visible=mastery.Visible=role!=0;if(previewFlow!=null)previewFlow.RowStyles[4].Height=role==0?0:44;starter.Text="Starter · Lv "+Adventure.RoleLevels[role];mastery.Text="Mastery · Lv "+Adventure.MasteryLevel(role);starter.Selected=previewRole>=0&&at<Adventure.MasteryLevel(role);mastery.Selected=at>=Adventure.MasteryLevel(role);starter.Invalidate();mastery.Invalidate();bool unlocked=Adventure.CanEquip(role,journey.Level);equip.Enabled=unlocked&&role!=draft.Role;equip.Text=role==draft.Role?"Equipped":unlocked?(at>journey.Level?"Equip available outfit":"Equip character"):"Unlocks at Level "+Adventure.RoleLevels[role];previewLabel.Text=previewRole>=0?(at>journey.Level?"Preview only · Earn Level "+at+" for this outfit.":"Preview only · Your progress stays saved."):Adventure.IsFixedDesign(role)?"Fixed design · Your personal look stays saved.":"Your customizable avatar · Changes save instantly.";returnToOwn.Visible=previewRole>=0;signature.Visible=skillHere;signature.Text=skill.Running?"Stop":"Use skill";signature.Selected=skill.Running;signature.Enabled=skillHere&&PixelMotion.Allowed(draft.Animations,SystemInformation.HighContrast,PixelMotion.SystemAnimationsEnabled,draft.MotionOverride);autoSkill.Visible=skillHere;autoSkill.Selected=draft.AutoSkills;autoSkill.Invalidate();if(quality!=null)quality.ColumnStyles[1].Width=skillHere?48:0;hints.SetToolTip(signature,signature.Enabled?CharacterSkills.Title(role)+" · Play here in the character preview":"Enable animation in Style to use skills");if(previewNav!=null)previewNav.ColumnStyles[1].Width=skillHere?120:0;hero.AccessibleName=skillHere?CharacterSkills.Name(role)+" portrait. Click to use skill here.":"Pixel adventurer. Click to cheer.";hints.SetToolTip(hero,role==13&&!skillHere?"Choose Mastery to preview his sword skill":skillHere?"Use "+CharacterSkills.Title(role)+" here":"Click to cheer");foreach(var tile in tiles){tile.Selected=tile.RoleIndex==role;tile.Equipped=tile.RoleIndex==draft.Role;tile.Invalidate();}}
        void LayoutContent(){LayoutTiles();LayoutStyle();journeyScroll.RefreshContent();}
        void Snapshot(string path){LayoutContent();Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(path);}}
        public void CapturePreview(string folder){long before=journey.Xp;SelectTab(0);name.Text="Pixel Courier";options["Look"][1].PerformClick();options["Hair colour"][5].PerformClick();Snapshot(Path.Combine(folder,"adventurer-style.png"));if(journey.Profile.Name!="Pixel Courier"||journey.Profile.Look!=1||journey.Profile.HairColour!=5)throw new Exception("Appearance did not autosave");SelectTab(1);Preview(6,100);Snapshot(Path.Combine(folder,"adventurer-characters.png"));if(journey.Profile.Role!=0||journey.Xp!=before)throw new Exception("A locked preview equipped or earned XP");SelectTab(2);Snapshot(Path.Combine(folder,"adventurer-ranks.png"));}
        protected override void Dispose(bool disposing){if(disposing){skill.Stop();hints.Dispose();}base.Dispose(disposing);}
    }
}
